///////// 5. 일반/업무 함수 영역 /////////

// 표준 API 조합으로 새로 작성한 검사 함수
/**
 * @method
 * @name scwin.CheckReqInfo_Cellphone
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm
 * @returns
 * @hidden N
*/
scwin.CheckReqInfo_Cellphone = async function (fm) { try { const v = (fm && fm.getValue) ? fm.getValue() : (fm && fm.value != null ? fm.value : null); if (v == null || String(v) === '') { return true; } if (!$c.str.isMobilePhone(String(v))) { await $c.win.alert('휴대전화번호 형식을 확인해 주세요.'); return false; } return true; } catch (_e) { return true; } };

/**
 * @method
 * @name scwin.mpd_files_selectCallback
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name scwin.searchIsuInfoChgList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchIsuInfoChgList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchIsuInfoChgList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    fm.action = '/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList';
    fm.target = '_self';
    await scwin.tx_fn_searchIsuInfoChgList();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    const fm = (document.SendForm || { elements: [] });
    $c.util.getComponent("dma_searchIsuInfoChgListReq").set("applIsuNm", $c.util.getComponent('ipt_divUnqIsuNm').getValue());
    $c.util.getComponent("dma_searchIsuInfoChgListReq").set("applIsuEngNm", $c.util.getComponent('ipt_divUnqIsuEngNm').getValue());
    fm.action = '/company/company.do?method=saveNondivideBw';
    await scwin.tx_fn_save();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkData = async function () {
    /* sdd-asis-lifecycle:begin fn_checkData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    const _mktact_cd = $c.util.getComponent("dma_searchIsuInfoChgListReq").get("bndMktactTpCd");
    const _now_time = dma_hiddenStore.get("areaNowTimer");
    const _isur_cd = $c.util.getComponent("dma_searchIsuInfoChgListReq").get("isurCd");
    if (!applTmCheck(_mktact_cd, _now_time, _isur_cd)) {
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_procsReqDd').getValue()) == 0) {
        await $c.win.alert("적용희망일을 입력하십시오.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return false;
    } else {
        if (WebSquare.date.getCurrentServerDate("yyyyMMdd") >= $c.util.getComponent('cal_procsReqDd').getValue().replace("-", "").replace("-", "")) {
            await $c.win.alert("적용희망일은 익일 이후만 입력가능합니다.");
            $c.util.getComponent("cal_procsReqDd").focus();
            return;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_divUnqIsuNm').getValue()) == 0) {
                await $c.win.alert("분리종목명을 입력하십시오.");
                $c.util.getComponent("ipt_divUnqIsuNm").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('ipt_divUnqIsuEngNm').getValue()) == 0) {
                    await $c.win.alert("분리종목영문명을 입력하십시오.");
                    $c.util.getComponent("ipt_divUnqIsuEngNm").focus();
                    return false;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('ipt_stkRelCorpbndExerPrc').getValue()) == 0) {
                        await $c.win.alert("행사가격을 입력하십시오.");
                        $c.util.getComponent("ipt_stkRelCorpbndExerPrc").focus();
                        return false;
                    } else {
                        if ($c.str.getByteLength($c.util.getComponent('ipt_exerShrs').getValue()) == 0) {
                            await $c.win.alert("주식수를 입력하십시오.");
                            $c.util.getComponent("ipt_exerShrs").focus();
                            return false;
                        } else {
                            if ($c.str.getByteLength($c.util.getComponent('ipt_exerAmt').getValue()) == 0) {
                                await $c.win.alert("최초행사금액을 입력하십시오.");
                                $c.util.getComponent("ipt_exerAmt").focus();
                                return false;
                            } else {
                                if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
                                    return false;
                                } else {
                                    if ($c.str.getByteLength($c.util.getComponent('slc_bdchrgTpCd').getValue()) == 0) {
                                        return false;
                                    } else {
                                        if (!scwin.CheckReqInfo_Cellphone(fm)) {
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


